import { ColorPanels, type ColorPanelsProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#3a3a52", "#4a4a68", "#52527a", "#5a5a8a"];

interface ShaderColorPanelsProps
  extends Omit<ColorPanelsProps, "frame" | "ref"> {}

function ShaderColorPanelsBase({
  speed = 1,
  colors = NEUTRAL_COLORS,
  colorBack = "#12121a",
  density = 3,
  length = 1.1,
  className,
  ...rest
}: ShaderColorPanelsProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-color-panels"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <ColorPanels
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colors={colors}
        colorBack={colorBack}
        density={density}
        length={length}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  density: {
    type: "number",
    min: 1,
    max: 8,
    step: 1,
    default: 3,
    description: "Density",
    hiddenFromList: false,
  },
  length: {
    type: "number",
    min: 0.5,
    max: 3,
    step: 0.1,
    default: 1.1,
    description: "Length",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","density","length","colorBack"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  density: 3,
  length: 1.1,
  colorBack: "#12121a",
};

type ShaderColorPanelsElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderColorPanelsBase>;

const ShaderColorPanelsInner = forwardRef<
  HTMLDivElement,
  ShaderColorPanelsElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderColorPanels>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderColorPanelsBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderColorPanelsBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderColorPanels = Interactive.withSchema({
  Component: ShaderColorPanelsInner,
  componentName: "<ShaderColorPanels>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
